<div class="page-title"><h1>Pesanan saya</h1><div class="muted">Pantau transaksi dan status pesananmu.</div></div><div class="order-list"><?php if (mysqli_num_rows($orders) === 0): ?><div class="panel"><p class="muted">Belum ada pesanan.</p><a class="btn btn-primary" href="/products">Mulai belanja</a></div><?php else: while ($order = mysqli_fetch_assoc($orders)): ?><article class="order-item"><div><strong>Pesanan #<?= (int) $order['id_penjualan']; ?></strong><span class="muted order-date"><?= e(date('d M Y', strtotime($order['tanggal_penjualan']))); ?> &middot; <?= e($order['metode'] ?: 'Cash'); ?></span></div><span class="status <?= in_array($order['status'], ['Proses', 'Dibatalkan'], true) ? 'process' : ''; ?>"><?= e(user_order_status_label($order['status'])); ?></span><strong class="order-total"><?= user_money($order['total_harga']); ?></strong><a class="btn btn-light order-link" href="/orders/detail?id=<?= (int) $order['id_penjualan']; ?>">Detail</a></article><?php endwhile; endif; ?></div>
